<script setup lang="ts">
import {ref,onMounted,computed} from 'vue';import {api,errorText} from '../lib/api';import {date,number,copy} from '../lib/format';import {useStatus} from '../lib/useStatus';import type {Configuration} from '../types';import Icon from '../components/Icon.vue';import Notice from '../components/Notice.vue';import EmptyState from '../components/EmptyState.vue';import Badge from '../components/Badge.vue';import Modal from '../components/Modal.vue'
const {status,error,loading,load}=useStatus();const config=ref<Configuration>(),message=ref(''),actionError=ref(''),busy=ref(false),applyOpen=ref(false)
onMounted(async()=>{try{config.value=await api<Configuration>('/api/admin/config')}catch(e){actionError.value=errorText(e)}})
const latest=computed(()=>[...(status.value?.history||[])].reverse().slice(0,5))
async function run(dry=true){busy.value=true;actionError.value='';message.value='';try{await api('/api/admin/run',{method:'POST',body:{dry_run:dry,...(!dry?{confirm_apply:true}:{})}});message.value=dry?'预览任务已提交，不会修改 DNS。':'同步任务已提交。';applyOpen.value=false;await load()}catch(e){actionError.value=errorText(e)}finally{busy.value=false}}
async function copyIPs(){try{await copy((status.value?.ips||[]).join(','));message.value='IP 已复制。'}catch(e){actionError.value=errorText(e)}}
</script>
<template><div class="admin-heading"><div><span class="eyebrow">OVERVIEW</span><h1>总览与统计</h1></div><button class="btn" :disabled="loading" @click="load"><Icon name="refresh" :class="{spinning:loading}" :size="17"/>刷新数据</button></div><Notice :message="error||actionError"/><Notice :message="message" kind="success"/><div class="stat-grid overview-totals"><article class="card"><div class="split"><span>累计运行</span><Icon name="chart"/></div><strong>{{number(status?.runs)}}</strong><small>包含预览与同步</small></article><article class="card"><div class="split"><span>待核对记录</span><Icon name="clock"/></div><strong>{{number(status?.pending_operations.length)}}</strong><RouterLink to="/admin/history">查看记录 ↗</RouterLink></article><article class="card"><div class="split"><span>优选 IP</span><Icon name="bolt"/></div><strong>{{number(status?.ips.length)}}</strong><small>来自已配置的 IP 源</small></article><article class="card"><div class="split"><span>DNS 目标</span><Icon name="globe"/></div><strong>{{number(config?.targets.length)}}</strong><RouterLink to="/admin/targets">管理目标 ↗</RouterLink></article></div><section v-if="config&&!config.targets.length" class="setup-banner"><span class="feature-icon"><Icon name="globe" :size="28"/></span><div><h2>初始化配置</h2><p>添加 DNS 目标与凭据，预览更新计划后再启用正式同步。</p><div class="button-row wrap"><RouterLink to="/admin/targets" class="btn primary small">1. 添加目标</RouterLink><button class="btn small" :disabled="busy||status?.status==='running'" @click="run()">2. 运行预览</button><RouterLink to="/admin/settings" class="btn small">3. 同步设置</RouterLink></div></div></section><section class="card section-gap"><div class="card-heading split"><div><h2>当前优选 IP</h2><p class="muted">{{status?.ips.length?'最近一次成功获取的地址':'等待获取来源数据'}}</p></div><button v-if="status?.ips.length" class="btn small" @click="copyIPs"><Icon name="copy" :size="16"/>复制</button></div><div v-if="status?.ips.length" class="ip-list"><div v-for="(ip,index) in status.ips" :key="ip" class="ip-row"><span class="ip-rank">{{String(index+1).padStart(2,'0')}}</span><code>{{ip}}</code><span class="badge active">IPv4</span></div></div><EmptyState v-else icon="globe" title="暂无有效 IP" text="来源请求成功后会显示真实地址。"/><div class="source-meta"><span>获取时间：{{date(status?.last_source_success)}}</span><Badge v-if="status" :value="status.ready?'active':'pending'"/></div></section><section class="card section-gap"><div class="card-heading split"><div><h2>任务运行</h2><p class="muted">{{config?.service.dry_run?'预览模式，不修改解析':'正式模式，按周期同步解析'}}</p></div><Badge v-if="status" :value="status.status"/></div><dl class="detail-list run-meta"><div><dt>运行周期</dt><dd>{{config?config.service.interval_seconds+' 秒':'—'}}</dd></div><div><dt>上次完成</dt><dd>{{date(status?.last_finished)}}</dd></div><div><dt>下次运行</dt><dd>{{date(status?.next_run_at)}}</dd></div><div><dt>上次模式</dt><dd>{{status?(status.dry_run?'预览':'正式同步'):'—'}}</dd></div></dl><Notice :message="status?.last_error"/><div class="button-row wrap"><button class="btn primary" :disabled="busy||status?.status==='running'" @click="run()"><Icon name="refresh" :size="17"/>{{busy?'提交中…':'立即预览'}}</button><button v-if="config&&!config.service.dry_run" class="btn" :disabled="busy||status?.status==='running'" @click="applyOpen=true">立即同步</button><RouterLink to="/admin/settings" class="text-link">调整设置 <Icon name="arrow" :size="16"/></RouterLink></div></section><section class="card section-gap"><div class="card-heading split"><h2>最近运行</h2><RouterLink to="/admin/history" class="text-link">全部记录 <Icon name="arrow" :size="16"/></RouterLink></div><div v-if="latest.length" class="table-scroll"><table><thead><tr><th>运行时间</th><th>模式</th><th>结果</th><th>计划 / 已核验</th></tr></thead><tbody><tr v-for="(run,index) in latest" :key="run.started_at+index"><td>{{date(run.started_at)}}</td><td><Badge :value="run.mode"/></td><td><Badge :value="run.status"/></td><td>{{run.planned}} / {{run.changed}}</td></tr></tbody></table></div><EmptyState v-else icon="clock" title="暂无运行记录" text="完成首次任务后会显示记录。"/></section><Modal :open="applyOpen" title="确认立即同步" :busy="busy" @close="applyOpen=false"><p>将读取最新 IP，并修改配置目标中需要更新的 A 记录。不会自动创建或删除解析。</p><Notice :message="actionError"/><div class="modal-actions"><button class="btn" :disabled="busy" @click="applyOpen=false">取消</button><button class="btn primary" :disabled="busy" @click="run(false)">确认同步</button></div></Modal></template>
